//! The bundled city list (GeoNames, CC BY 4.0), generated by `tools/cities.py`.

use std::sync::OnceLock;

use chrono_tz::Tz;
use thiserror::Error;

const CSV: &str = include_str!("../data/cities.csv");

/// One city from the bundled list.
#[derive(Clone, Debug, PartialEq)]
pub struct City {
    pub name: &'static str,
    pub ascii: &'static str,
    pub country: &'static str,
    pub tz: Tz,
    pub lat: f64,
    pub lon: f64,
}

/// Why a city name did not resolve to exactly one city.
#[derive(Clone, Debug, Error, PartialEq, Eq)]
pub enum CityError {
    #[error("unknown city \"{name}\"")]
    Unknown { name: String },
    #[error("city \"{name}\" is ambiguous: {}", .candidates.join("; "))]
    Ambiguous {
        name: String,
        candidates: Vec<String>,
    },
}

/// Every city in the bundled list, parsed once.
pub fn all() -> &'static [City] {
    static CITIES: OnceLock<Vec<City>> = OnceLock::new();
    CITIES.get_or_init(|| CSV.lines().skip(1).filter_map(parse_row).collect())
}

fn parse_row(line: &'static str) -> Option<City> {
    let mut fields = line.split(',');
    let mut next = || fields.next();
    Some(City {
        name: next()?,
        ascii: next()?,
        country: next()?,
        tz: next()?.parse().ok()?,
        lat: next()?.parse().ok()?,
        lon: next()?.parse().ok()?,
    })
}

/// The one city whose name or ASCII name matches `name`, ignoring case.
///
/// # Errors
///
/// [`CityError::Unknown`] when nothing matches, and [`CityError::Ambiguous`] (listing
/// `name, country` for each candidate) when more than one city does.
pub fn lookup(name: &str) -> Result<&'static City, CityError> {
    let matches: Vec<&City> = all()
        .iter()
        .filter(|city| {
            city.name.eq_ignore_ascii_case(name) || city.ascii.eq_ignore_ascii_case(name)
        })
        .collect();
    match matches.as_slice() {
        [city] => Ok(city),
        [] => Err(CityError::Unknown {
            name: name.to_owned(),
        }),
        several => Err(CityError::Ambiguous {
            name: name.to_owned(),
            candidates: several
                .iter()
                .map(|city| format!("{}, {}", city.name, city.country))
                .collect(),
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_row_of_the_bundled_list_parses() {
        assert_eq!(all().len(), CSV.lines().count() - 1);
    }

    #[test]
    fn a_lookup_ignores_case_and_returns_the_zone() {
        let city = lookup("melbourne").unwrap();
        assert_eq!(
            (city.name, city.country, city.tz),
            ("Melbourne", "AU", chrono_tz::Australia::Melbourne)
        );
    }

    #[test]
    fn austin_is_in_the_list_although_it_is_neither_a_capital_nor_a_million() {
        assert_eq!(lookup("Austin").unwrap().tz, chrono_tz::America::Chicago);
    }

    #[test]
    fn an_ambiguous_name_lists_name_and_country_candidates() {
        assert_eq!(
            lookup("Hyderabad").unwrap_err().to_string(),
            "city \"Hyderabad\" is ambiguous: Hyderabad, IN; Hyderabad, PK"
        );
    }

    #[test]
    fn an_unknown_name_is_an_error() {
        assert_eq!(
            lookup("Atlantis").unwrap_err().to_string(),
            "unknown city \"Atlantis\""
        );
    }
}
